 const theme=node('select');theme.setAttribute('aria-label','Paper theme');for(const[v,t]of [['system','Follow system'],['light','White'],['cream','Cream'],['dark','Night']])theme.append(new Option(t,v));theme.value=themeChoice;theme.onchange=()=>{themeChoice=theme.value;applyTheme();try{localStorage.setItem('expense-book.theme',themeChoice);}catch{notice('Theme changed for this session.');}};root.append(heading('Paper',theme));
 root.append(button('Add a currency',()=>form('Add active currency',[field('currency','Search by currency code')],async d=>{const c=d.currency.toUpperCase();digits(c);const next=structuredClone(state);next.settings.activeCurrencies=[...new Set([...next.settings.activeCurrencies,c])];next.revision++;await persist(next);})));root.append(simpleRow('Active currencies',state.settings.activeCurrencies.join(', '),[button('Change currencies',()=>form('Active currencies',[field('codes','Currency codes, comma separated','text',state.settings.activeCurrencies.join(', '))],async d=>{const codes=[...new Set(d.codes.toUpperCase().split(',').map(s=>s.trim()).filter(Boolean))];for(const c of codes)digits(c);const next=structuredClone(state);next.settings.activeCurrencies=codes;next.revision++;await persist(next);} ))]));root.append(simpleRow('Reporting currency',state.settings.reportingCurrency,[button('Change reporting currency',reportCurrencyForm)]));
 root.append(button('Export full backup',()=>download(JSON.stringify(state,null,2),`expense-book-${today()}.json`)),button('Export CSV',()=>download(csv([['id','date','kind','status','amount','currency','category','account','pot','note'],...state.entries.map(e=>[e.id,e.date,e.kind,e.status,humanAmount(e.minor,e.precision),e.currency,name('categories',e.category),name('accounts',e.account),name('pots',e.pot),e.note])]),`expense-book-${today()}.csv`,'text/csv')));
 const file=node('input');file.type='file';file.accept='.json,application/json';file.setAttribute('aria-label','Import full backup');file.onchange=async()=>{try{const f=file.files[0];if(!f)return;if(f.size>10*1024*1024)throw Error('Choose a backup smaller than 10 MB.');const data=JSON.parse(await f.text()),incoming=data.version===1?migrate(data,today()):validateState(data);if(!confirm('Restore this full backup? It replaces the current local ledger. Export your current copy first.'))return;incoming.revision=state.revision+1;await persist(incoming,'Backup restored.');}catch(e){notice(errorText(e));}finally{file.value='';}};root.append(heading('Restore a full backup',file),text('Restoration replaces the local ledger after full validation. Export first. The original preview copy is retained in local storage after migration.'));
 const csvFile=node('input');csvFile.type='file';csvFile.accept='.csv,text/csv';csvFile.setAttribute('aria-label','Import historical CSV');csvFile.onchange=async()=>{try{const file=csvFile.files[0];if(!file)return;if(file.size>5*1024*1024)throw Error('CSV must be below 5 MB.');const result=historicalImport(state,await file.text());if(confirm(`Import ${result.added} historical expenses? These will not affect current account balances or pots.`))await persist(result.state,'Historical expenses imported.');}catch(e){notice(errorText(e));}finally{csvFile.value='';}};root.append(heading('Historical CSV import',csvFile),text('Required columns: date, amount, currency, category. Optional: id, note, tags. Dates use YYYY-MM-DD. Historical imports are read-only and excluded from current balances.'));
