const catalogue=node('datalist');catalogue.id='currency-catalogue';const currencyNames=Intl.DisplayNames?new Intl.DisplayNames(['en'],{type:'currency'}):null;for(const c of (Intl.supportedValuesOf?Intl.supportedValuesOf('currency'):['GBP','CNY','USD','EUR','JPY'])){const option=new Option(currencyNames?.of(c)||c,c);catalogue.append(option);}document.body.append(catalogue);
$('#add').onclick=()=>{try{if(!state)throw Error('Wait for the database to open.');entryForm();}catch(e){notice(errorText(e));}};
